package com.dairycoopms.dairycoopms.model;

import jakarta.persistence.*;
import lombok.*;
import java.time.LocalDateTime;
import java.util.UUID;

/**
 * Stores a finance report generated by the Accounts Officer
 * and submitted to the Admin for review via the portal.
 */
@Entity
@Table(name = "report_submissions", schema = "dairycoopms")
@Data
@NoArgsConstructor
@AllArgsConstructor
@Builder
public class ReportSubmission {

    @Id
    @GeneratedValue(strategy = GenerationType.UUID)
    @Column(name = "id", columnDefinition = "BINARY(16)", nullable = false, updatable = false)
    private UUID id;

    /** The accounts officer who generated + sent this report */
    @ManyToOne(fetch = FetchType.LAZY)
    @JoinColumn(name = "submitted_by", nullable = false)
    private User submittedBy;

    /** When the report was generated */
    @Column(name = "generated_at", nullable = false)
    private LocalDateTime generatedAt;

    /** When it was sent to admin (null if still draft) */
    @Column(name = "sent_at")
    private LocalDateTime sentAt;

    /** Whether admin has read/opened it */
    @Column(name = "read_by_admin", nullable = false)
    @Builder.Default
    private boolean readByAdmin = false;

    @Column(name = "read_at")
    private LocalDateTime readAt;

    /** Full report JSON stored as text — used for chart rendering */
    @Column(name = "report_data", columnDefinition = "LONGTEXT", nullable = false)
    private String reportData;

    /** Period label e.g. "April 2026" */
    @Column(name = "period_label", length = 50)
    private String periodLabel;

    @PrePersist
    protected void onCreate() {
        if (generatedAt == null) generatedAt = LocalDateTime.now();
    }
}